head.b:skin:
/* The real styles load from GitHub (assets/syg.css). This only stops a white flash. */
html{background:#06080c}
html[data-theme='light']{background:#f4f6fa}

body.script:
//
window.SYG = {
  /* EDIT: where the fast group list lives (GitHub Pages) */
  dataUrl: 'https://YOUR-GITHUB-USER.github.io/YOUR-REPO/data/groups.json',
  /* EDIT: your Google Apps Script web app URL (submissions go here) */
  apiUrl: 'https://script.google.com/macros/s/YOUR-APPS-SCRIPT-ID/exec',
  perPage: 24,        /* groups loaded per scroll */
  adEvery: 6,         /* EDIT: promo/ad card after every 6 groups (0 = off) */
  adClient: 'ca-pub-0000000000000000',   /* EDIT: your AdSense publisher id */
  adSlot: '',         /* EDIT: AdSense ad unit id for the card slots (empty = promo card only) */
  disqus: '',
  siteName: 'ShareYourGroup'
};
//
